python3 << 'EOF'
import zipfile
import xml.etree.ElementTree as ET

M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

def cell_val(c):
    t = c.attrib.get('t')
    v = c.find(M + 'v')
    is_ = c.find(M + 'is')
    if t == 'inlineStr' and is_ is not None:
        return ''.join(x.text or '' for x in is_.iter(M + 't'))
    if v is not None and v.text:
        return float(v.text)
    return None

total = 0
by_cat = {}
for row in root.iter(M + 'row'):
    r = int(row.attrib['r'])
    if 11 <= r <= 22:
        cells = {c.attrib['r'][0]: cell_val(c) for c in row.iter(M + 'c')}
        cat, item, amt = cells.get('A'), cells.get('B'), cells.get('C')
        total += amt
        by_cat[cat] = by_cat.get(cat, 0) + amt
        print('%2d | %-15s | %-18s | %8.2f' % (r, cat, item, amt))

print('-' * 50)
print('TOTAL EXPENSES: %.2f' % total)
for cat in by_cat:
    print('  %-15s %.2f' % (cat, by_cat[cat]))
EOF
